package main

import (
	"bytes"
	"os"
	"os/exec"
	"path/filepath"
)

func getLsResult(dirPath string) string {
	// Clean the directory path to prevent command injection
	cleanPath := filepath.Clean(dirPath)

	// Check if the directory exists and is accessible
	info, err := os.Lstat(cleanPath)
	if err != nil || !info.IsDir() {
		return ""
	}

	// Execute the command safely without shell interpretation
	cmd := exec.Command("ls", "-l", cleanPath)
	var out bytes.Buffer
	cmd.Stdout = &out
	err = cmd.Run()
	if err != nil {
		return ""
	}
	return out.String()
}
```

### Explanation:
- **Path Cleaning**: The `filepath.Clean` function is used to sanitize the input path, reducing the risk of command injection.
- **Directory Validation**: `os.Lstat` is used instead of `os.Stat` to prevent symbolic link traversal attacks. This ensures that the path is a directory and not a symlink.
- **Command Execution**: The `exec.Command` function is used to run the `ls -l` command without shell interpretation, which is safer.
- **Error Handling**: If any error occurs during the execution of the command or if the path is invalid, the function returns an empty string.

